import 'package:flutter/material.dart';
import 'package:hydrowin/app/app_scope.dart';
import 'package:hydrowin/app/cloud_scope.dart';
import 'package:hydrowin/domain/user_roles.dart';
import 'package:go_router/go_router.dart';

class SettingsScreen extends StatefulWidget {
  const SettingsScreen({super.key});

  @override
  State<SettingsScreen> createState() => _SettingsScreenState();
}

class _SettingsScreenState extends State<SettingsScreen> {
  int _versionTapCount = 0;
  bool _isAdmin = true;
  String? _roleLabel;
  String? _userName;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) => _loadRole());
  }

  Future<void> _loadRole() async {
    final auth = CloudScope.of(context).auth;
    final role = await auth.currentRole();
    final name = await auth.currentUserName();
    final admin = await auth.isAdmin();
    if (!mounted) return;
    setState(() {
      _isAdmin = admin;
      _roleLabel = UserRoles.label(role);
      _userName = name;
    });
  }

  void _onVersionTap() {
    if (!_isAdmin) return;
    _versionTapCount++;
    if (_versionTapCount >= 7) {
      _versionTapCount = 0;
      context.push('/settings/developer');
    }
  }

  Future<void> _logout() async {
    await CloudScope.of(context).auth.logout();
    if (!mounted) return;
    context.go('/login');
  }

  @override
  Widget build(BuildContext context) {
    final session = AppScope.of(context);

    return Scaffold(
      appBar: AppBar(
        title: const Text('Настройки'),
        leading: context.canPop()
            ? BackButton(onPressed: () => context.pop())
            : null,
      ),
      body: ListenableBuilder(
        listenable: session,
        builder: (context, _) {
          return ListView(
            children: [
              if (_userName != null || _roleLabel != null)
                ListTile(
                  leading: const Icon(Icons.person_outline),
                  title: Text(_userName ?? 'Пользователь'),
                  subtitle: Text(_roleLabel ?? ''),
                ),
              ListTile(
                title: const Text('Частота обновления'),
                subtitle: Text('${session.pollSeconds} сек'),
              ),
              Padding(
                padding: const EdgeInsets.symmetric(horizontal: 16.0),
                child: Slider(
                  value: session.pollSeconds.toDouble(),
                  min: 1,
                  max: 60,
                  divisions: 59,
                  label: '${session.pollSeconds} с',
                  onChanged: (v) => session.setPollSeconds(v.round()),
                ),
              ),
              const Divider(),
              if (_isAdmin) ...[
                ListTile(
                  title: const Text('Редактировать датчики'),
                  onTap: () => context.push('/sensors/setup?from=settings'),
                ),
                ListTile(
                  leading: const Icon(Icons.wifi),
                  title: const Text('Настройки сети'),
                  subtitle: const Text('Wi‑Fi / GSM блока, адрес сервера'),
                  onTap: () => context.push('/settings/network'),
                ),
                ListTile(
                  leading: const Icon(Icons.developer_mode),
                  title: const Text('Режим разработчика'),
                  subtitle: const Text('IP, порты API (по паролю)'),
                  onTap: () => context.push('/settings/developer'),
                ),
                ListTile(
                  title: const Text('Сменить режим работы'),
                  onTap: () => context.go('/mode'),
                ),
              ] else
                const ListTile(
                  leading: Icon(Icons.lock_outline),
                  title: Text('Настройки оборудования'),
                  subtitle: Text(
                    'Доступны только администратору (ESP32, датчики, сеть)',
                  ),
                ),
              ListTile(
                title: const Text('Выйти'),
                leading: const Icon(Icons.logout),
                onTap: _logout,
              ),
              ListTile(
                title: const Text('О приложении'),
                subtitle: const Text('ГидроВин v1.1.0'),
                onTap: _onVersionTap,
              ),
            ],
          );
        },
      ),
    );
  }
}
